function toneFor(x){if(['Satisfied','Accepted','Approved','Effective','Within limit','Active','Current','Completed'].includes(x))return 'green';if(['Not satisfied','Ineffective','Breached','High','Critical','Overdue'].includes(x))return 'red';if(['Partially satisfied','Partially effective','Needs refresh','Expired','Challenge requested','Near limit','Remediation'].includes(x))return 'amber';if(['Submitted','In review','Due diligence','Draft','Onboarding'].includes(x))return 'blue';return '';}
const notice=(text,type='')=>`<div class="notice ${type}">${icon(type==='warning'?'risk':'info')}<div>${text}</div></div>`;
const metric=(label,value,note,ic='chart')=>`<div class="panel metric"><div class="label">${e(label)}${icon(ic)}</div><div class="value">${value}</div><small>${note}</small></div>`;
const metricRow=items=>`<div class="metrics">${items.join('')}</div>`;
const panel=(title,subtitle,body,action='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>${body}</section>`;
const empty=(title,desc,action='')=>`<div class="empty">${icon('file')}<h3>${title}</h3><p>${desc}</p>${action}</div>`;
const num=(n)=>new Intl.NumberFormat('en-GB').format(n);
const ngn=k=>`₦${new Intl.NumberFormat('en-NG',{maximumFractionDigits:2}).format(k/100)}`;
const moneyShort=k=>Math.abs(k)>=1e8?`₦${(k/1e8).toFixed(1)}m`:ngn(k);
const date=x=>x?new Date(x+'T00:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'Not observed';
const days=(a,b)=>Math.floor((Date.parse(a+'T00:00:00Z')-Date.parse(b+'T00:00:00Z'))/864e5);
const addDays=(x,n)=>new Date(Date.parse(x+'T00:00:00Z')+n*864e5).toISOString().slice(0,10);
const findR=id=>R.find(x=>x.id===id);const findQ=id=>Q.find(x=>x.id===id);
const fw=id=>FW.find(x=>x.id===id)||FW[0];
const uniqueQ=reqs=>[...new Set(reqs.flatMap(id=>findR(id)?.questions||[]))].map(findQ);
const targetName=id=>{const t=S.engagements.find(x=>x.id===id);return t?`${S.vendors.find(v=>v.id===t.vendorId)?.name} · ${t.service}`:id;};
const options=(values,selected='')=>values.map(x=>{const a=Array.isArray(x)?x:[x,x];return `<option value="${e(a[0])}" ${a[0]===selected?'selected':''}>${e(a[1])}</option>`;}).join('');
const select=(name,label,values,value='',extra='')=>`<label>${label}<select name="${name}" ${extra}>${options(values,value)}</select></label>`;
const input=(name,label,value='',type='text',extra='')=>`<label>${label}<input name="${name}" value="${e(value)}" type="${type}" ${extra}></label>`;
const area=(name,label,value='',extra='')=>`<label>${label}<textarea name="${name}" ${extra}>${e(value)}</textarea></label>`;
const score=r=>r[0]*r[1];
const scoreBadge=(r)=>`<span class="risk-score ${score(r)>9?'high':score(r)>4?'mid':''}">${score(r)}</span>`;
const table=(headers,rows,id='')=>`<div class="table-wrap"><table class="table" ${id?`id="${id}"`:''}><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr ${r.attrs||''}>${r.cells.map((c,i)=>`<td data-label="${e(headers[i])}">${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">${empty('No matching records','Change the filters or add a demo record.')}</td></tr>`}</tbody></table></div>`;
const tools=(placeholder='Search records',extra='')=>`<div class="toolbar"><label class="search"><span class="sr-only">${e(placeholder)}</span>${icon('search')}<input data-filter placeholder="${e(placeholder)}"></label>${extra}<span class="small muted" id="filter-count"></span></div>`;
const noMatch='<div id="no-match" hidden class="panel empty">No records match these filters.</div>';
const unitFilter=()=>`<select aria-label="Business unit filter" data-unit-filter>${options([['','All units'],...CS_SEED.units])}</select>`;
const tabLinks=(items,active)=>`<nav class="tabs" aria-label="Section navigation">${items.map(([text,url,key])=>`<a href="#/${url}" class="${key===active?'active':''}" ${key===active?'aria-current="page"':''}>${text}</a>`).join('')}</nav>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(S));}catch(_){storageOK=false;toast('Browser storage is unavailable. Changes remain in this open tab only.');}}
function audit(text,ref='',actor='Demo operator'){S.activity.unshift({id:uid('LOG'),text,ref,actor,time:new Date().toISOString()});S.activity=S.activity.slice(0,200);save();}
function uid(prefix){return prefix+'-'+(globalThis.crypto?.randomUUID?.().slice(0,8)||Date.now().toString(36)+Math.random().toString(36).slice(2,6));}
function toast(text){$('#toast').textContent=text;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',4400);}
function go(route){if(location.hash==='#/'+route)render();else location.hash='/'+route;}
function route(){const parts=(location.hash.replace(/^#\//,'')||document.body.dataset.start||'home').split('?');return {name:parts[0],params:new URLSearchParams(parts[1]||'')};}
let current={},lastFocus=null,modalSave=null,filters={search:'',unit:'',matrix:''},wizardStep=1,selectedFramework='FW-BANK';
function prog(){return S.programs.find(p=>p.id===current.params.get('id'))||S.programs[0];}
function selectedTarget(p){const t=current.params.get('target');return p.targets.includes(t)?t:p.targets[0];}
function activeReqs(p){return p.reqs.filter(id=>!p.excluded?.[id]);}
function evaluation(p,t,r){return p.evaluations?.[t]?.[r]||{status:'Not assessed'};}
function posture(p,t){const reqs=activeReqs(p),v=reqs.map(r=>evaluation(p,t,r));const reviewed=v.filter(x=>['Satisfied','Partially satisfied','Not satisfied'].includes(x.status)).length;return {all:reqs.length,reviewed,pass:v.filter(x=>x.status==='Satisfied').length,partial:v.filter(x=>x.status==='Partially satisfied').length,failed:v.filter(x=>x.status==='Not satisfied').length,stale:v.filter(x=>x.status==='Needs refresh').length,unassessed:v.filter(x=>x.status==='Not assessed').length};}
function evQuality(x){
  const isDate=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v+'T00:00:00Z'))&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v;
  if(!isDate(x.observed)||!isDate(x.expires)||x.expires<x.observed)return 'Unknown';
  if(x.observed>S.asOf)return 'Not yet current';
  return x.expires<S.asOf?'Needs refresh':'Current';
}
function indicatorState(x){if(typeof x.value!=='number'||!Number.isFinite(x.value)||typeof x.observed!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(x.observed)||!Number.isFinite(Date.parse(x.observed+'T00:00:00Z'))||new Date(x.observed+'T00:00:00Z').toISOString().slice(0,10)!==x.observed||x.observed>S.asOf)return 'Unknown';if(days(S.asOf,x.observed)>x.freshDays)return 'Needs refresh';if(x.direction==='above'?x.value>x.threshold:x.value<x.threshold)return 'Breached';if(x.direction==='above'?x.value>x.warning:x.value<x.warning)return 'Near limit';return 'Within limit';}
function recoveries(l){return l.recoveries.reduce((n,r)=>n+r.amount,0);}
function scopedLosses(){return scopeLosses();}
function assessmentKey(p,t){return p.id+'::'+t;}
function getAssessment(p,t){const key=assessmentKey(p,t);return S.assessments[key]||{answers:{},evidence:{},status:'Draft'};}
function draft(){if(!S.draft){const f=fw(selectedFramework);S.draft={frameworkId:f.id,name:f.name+' · 2026',scopeType:f.id==='FW-VENDOR'?'vendor':'bank',targets:f.id==='FW-VENDOR'?['ENG-01']:['Meridian Bank'],reqs:[...f.reqs],excluded:{},overrides:{},rules:{},assignments:{},owner:'Amina Bello',reviewer:'Ifeoma Nwosu',respondents:['Information Security','Technology'],due:'2026-11-30',cadence:'Quarterly'};save();}return S.draft;}
function draftErrors(d){const issues=[];if(!d.name?.trim())issues.push('Enter a program name.');if(!d.targets?.length)issues.push('Choose at least one assessment target.');if(!activeReqs(d).length)issues.push('Keep at least one applicable requirement.');if(Object.values(d.excluded||{}).some(x=>!String(x).trim()))issues.push('Provide a rationale for every not-applicable requirement.');if(!d.owner)issues.push('Choose a program owner.');if(!d.respondents?.length)issues.push('Assign at least one respondent unit.');if(!d.reviewer)issues.push('Choose a reviewer.');if(d.reviewer===d.owner)issues.push('Assign an independent reviewer different from the program owner.');if(!d.due||d.due<S.asOf)issues.push('Use an assessment due date on or after 13 November 2026.');return issues;}
