$('#app').innerHTML=`<a href="#main-content" class="skip">Skip to main content</a><button class="mobile-shade" data-action="menu-close" aria-label="Close navigation"></button><aside class="sidebar" aria-label="Primary navigation"><div class="ix-sidebar-bank"><span class="bank-logo">M</span><div><strong>Meridian Bank</strong><small>Synthetic workspace</small></div></div><div class="nav-label">Workspace</div><nav>${nav.map(([id,title,ic])=>`<a class="nav-link ${active===id?'active':''}" href="#/${id}" ${active===id?'aria-current="page"':''}>${icon(ic)}<span>${title}</span>${id==='work'?`<b class="count">${count}</b>`:''}</a>`).join('')}</nav><div class="side-foot"><a class="nav-link ${active==='settings'?'active':''}" href="#/settings">${icon('settings')}<span>Settings</span></a><div class="small faint" style="padding:12px">V2.8 · Demo workspace</div></div></aside><div class="workspace"><header class="topbar">${btn(icon('menu'),'menu','aria-label="Open navigation"','icon-only mobile-menu')}<a class="brand" href="#/home"><div class="logo-mark"><i class="a"></i><i class="b"></i><i class="c"></i></div><div><strong>ClearSight</strong><small>GOVERNANCE · RISK · COMPLIANCE</small></div></a>${scopeBar()}<div class="grow"></div><button class="search-trigger" data-action="search" aria-label="Search demo records">${icon('search')}<span>Search ClearSight</span><kbd>⌘ K</kbd></button>${btn(icon('sun'),'theme','aria-label="Toggle light or dark theme"','icon-only quiet')}<div class="profile" title="Demo actor: ${e(recActor().name)}"><div class="avatar">${e(recActor().name.split(/\s+/).map(n=>n[0]).slice(0,2).join(''))}</div><div><strong>${e(recActor().name)}</strong><small>Demo actor · not authenticated</small></div></div></header><main id="main-content" class="page" tabindex="-1"></main></div>`;
