function lossesView(){const losses=scopedLosses(),gross=losses.reduce((s,x)=>s+x.gross,0),rec=losses.reduce((s,x)=>s+recoveries(x),0),period=scopePeriod();return header('Loss events',scopeLabel()+' · All amounts in NGN.',btn(icon('download')+' Export CSV','export-losses')+' '+btn(icon('plus')+' Record loss','new-loss','','primary'),'Loss register')+riskTabs('losses')+metricRow([metric('Gross loss',moneyShort(gross),`Events occurring in the last ${period} days`,'chart'),metric('Recovered',moneyShort(rec),'Recoveries to snapshot date for selected events','refresh'),metric('Net loss',moneyShort(gross-rec),'Gross − recoveries · not risk exposure','chart'),metric('Near misses',losses.filter(x=>x.type==='Near miss').length,'Zero booked loss · reported separately','shield')])+tools('Search loss event',`<select aria-label="Loss occurrence period" data-loss-period>${options([['30','Last 30 days'],['90','Last 90 days'],['365','Last 365 days']],String(period))}</select>`)+`<div class="panel">${table(['Event','Occurred / unit','Gross loss','Recovered','Net loss',''],[...losses].sort((a,b)=>b.date.localeCompare(a.date)).map(l=>({attrs:`data-search="${e(l.id+' '+l.title+' '+l.risk+' '+l.unit)}"`,cells:[`<strong>${e(l.title)}</strong><small>${l.id} · ${l.risk} · ${l.type}</small>`,`${date(l.date)}<small>${e(orgName(l.orgScopeId)||'Scope unassigned')}</small>`,`<span class="num">${ngn(l.gross)}</span>`,`<span class="num">${ngn(recoveries(l))}</span>`,`<strong class="num">${ngn(l.gross-recoveries(l))}</strong>`,btn('Open','loss-detail',`data-id="${l.id}"`,'small')]})))}</div>${noMatch}<div class="notice mt16">${icon('info')}<div>Amounts are stored as integer kobo. Recovery entries cannot exceed outstanding gross loss. Near misses do not contribute to monetary totals.</div></div>`;}
