function privacyView(){return header('Privacy & data','Processing activities, supporting assessments and review ownership.',btn(icon('plus')+' Add processing activity','new-processing','','primary'),'Privacy workspace')+notice('Retention periods and privacy statuses below are fictional internal examples, not statements of legal requirements.')+metricRow([metric('Processing activities',scopeItems('processing').length,'Documented purpose and data scope','form'),metric('DPIAs in review',scopeItems('processing').filter(x=>x.dpia==='In review').length,'Independent review before approval','work'),metric('Vendor-supported activities',scopeItems('processing').filter(x=>x.vendor!=='Internal').length,'Follow the service relationship for assurance','vendors'),metric('Approved DPIAs',scopeItems('processing').filter(x=>x.dpia==='Approved').length,'Demo decisions only','shield')])+tools('Search processing activities',unitFilter())+panel('Record of processing activities','Specialist privacy records use the same ownership and evidence model.',table(['Activity & purpose','Unit / owner','Data / supplier','DPIA',''],scopeItems('processing').map(x=>({attrs:`data-search="${e(x.name+' '+x.purpose+' '+x.vendor)}" data-unit="${e(x.unit)}"`,cells:[`<strong>${e(x.name)}</strong><small>${x.id} · ${e(x.purpose)}</small>`,`${e(x.unit)}<small>${e(x.owner)}</small>`,`${e(x.data)}<small>${e(x.vendor)}</small>`,pill(x.dpia),btn('Review','processing-detail',`data-id="${x.id}"`,'small')]}))))+noMatch;}
function workItems(){const rows=S.tasks.map(x=>({...x,source:'task'}));for(const [key,a]of Object.entries(S.assessments)){if(a.status==='Submitted'){const [pid,t]=key.split('::'),p=S.programs.find(x=>x.id===pid);if(!p)continue;const open=activeReqs(p).filter(id=>!a.reviewedReqs?.includes(id));if(open.length)rows.unshift({id:key,title:`Review ${p.name} · ${targetName(t)}`,kind:'Assessment review',owner:p.reviewer,due:p.due,status:'Open',route:`program?id=${p.id}&target=${encodeURIComponent(t)}&tab=requirements`,ref:p.id,source:'assessment'});}}
for(const c of S.cycles)for(const [rid,r]of Object.entries(c.reviews)){if(r.status==='Submitted')rows.unshift({id:c.id+rid,title:`Challenge ${S.risks.find(x=>x.id===rid)?.title}`,kind:'RCSA approval',owner:c.reviewer,due:c.due,status:'Open',route:`rcsa-review?id=${c.id}&risk=${rid}&mode=review`,source:'rcsa'});}return rows;}
function workView(){const rows=workItems(),tab=current.params.get('tab')||'open',items=rows.filter(x=>tab==='all'||(tab==='open'?x.status==='Open':uxIsReviewItem(x)));return header('Work & approvals','One queue for document reviews, assessment responses, remediation and independent challenge.',btn(icon('plus')+' Create action','new-action','','primary'),'My work')+metricRow([metric('Open work',rows.filter(x=>x.status==='Open').length,'Material decisions link to their source records','work'),metric('Overdue',rows.filter(x=>x.status==='Open'&&x.due<S.asOf).length,'Due before the demonstration snapshot','clock'),metric('Pending RCSA decisions',rows.filter(x=>x.source==='rcsa').length,'Self-approval is blocked','shield'),metric('Completed actions',rows.filter(x=>x.status==='Completed').length,'Local audit history retained','check')])+tabLinks([['Open work','work?tab=open','open'],['Reviews & approvals','work?tab=review','review'],['All work','work?tab=all','all']],tab)+tools('Search work items')+`<div class="panel">${table(['Work item','Type','Owner','Due','State',''],items.map(x=>({attrs:`data-search="${e(x.title+' '+x.owner+' '+x.kind)}"`,cells:[`<strong>${e(x.title)}</strong><small>${e(x.ref||x.id)}</small>`,e(typeof d210WorkLabel==='function'?d210WorkLabel(x.kind):x.kind),e(x.owner),date(x.due),pill(x.status==='Open'&&x.due<S.asOf?'Overdue':x.status),x.source==='task'?btn('Review','task-detail',`data-id="${x.id}"`,'small'):link('Open decision',x.route,'small')]})))}</div>${noMatch}`;}
function reportData(){return {generatedAt:new Date().toISOString(),asOf:S.asOf,organization:S.organization,synthetic:true,programs:scopeItems('programs').map(p=>({id:p.id,name:p.name,type:p.scopeType,targets:p.targets.map(t=>({id:t,name:targetName(t),...posture(p,t)}))})),risk:{total:scopeItems('risks').length,aboveAppetite:scopeItems('risks').filter(r=>score(r.residual)>r.appetite).length},losses:{currency:'NGN',minorUnit:'kobo',gross:scopeItems('losses').reduce((s,x)=>s+x.gross,0),recoveries:scopeItems('losses').reduce((s,x)=>s+recoveries(x),0),net:scopeItems('losses').reduce((s,x)=>s+x.gross-recoveries(x),0)},evidence:{records:scopeItems('evidence').length,stale:scopeItems('evidence').filter(x=>evQuality(x)==='Needs refresh').length}};}
function reportsView(){const x=reportData();return header('Reports & insights','Explainable numbers, explicit scope and exportable source records.',btn(icon('download')+' Export snapshot','report-export')+' '+btn(icon('eye')+' Print report','print','','primary'),'Reporting')+notice('Bank compliance and third-party assurance are reported separately. Scores use the applicable scoped requirement denominator; unanswered obligations stay in scope.')+`<div class="split"><div class="stack">${panel('Assurance by program','Current requirement outcomes · snapshot '+date(S.asOf),table(['Program','Basis','Applicable','Current coverage','Satisfied'],scopeItems('programs').flatMap(p=>p.targets.map(t=>{const z=posture(p,t);return {cells:[`<strong>${e(p.name)}</strong><small>${e(targetName(t))}</small>`,p.scopeType==='vendor'?'Vendor assurance':'Bank / internal',z.all,`${z.reviewed}/${z.all}`,`${z.pass}/${z.all}`]};}))))}${panel('Operational loss reconciliation',scopeLabel()+' · Last '+scopePeriod()+' days by occurrence; recoveries through snapshot.',`<div class="pad"><div class="stat-list"><div><span>Gross loss</span><strong>${ngn(x.losses.gross)}</strong></div><div><span>Less recoveries</span><strong>${ngn(x.losses.recoveries)}</strong></div><div><span>Net loss</span><strong>${ngn(x.losses.net)}</strong></div></div><hr class="divider">${link('Inspect loss ledger','losses','small')}</div>`)}</div><aside class="stack">${panel('Export formats','',`<div class="pad stack">${btn(icon('download')+' Program posture CSV','export-programs','','wide')}${btn(icon('download')+' Loss events CSV','export-losses','','wide')}${btn(icon('download')+' Full report JSON','report-export','','wide')}<p class="small mb0">CSV exports neutralize spreadsheet formula prefixes. JSON preserves explicit denominators and scope identifiers.</p></div>`)}${panel('Calculation notes','',`<div class="pad"><p class="small"><strong>Coverage:</strong> current accepted evaluations ÷ applicable requirements.</p><p class="small"><strong>Satisfaction:</strong> satisfied requirements ÷ applicable requirements. Partial outcomes are not counted as full passes.</p><p class="small"><strong>Residual risk:</strong> independently accepted likelihood × impact. No formulaic control-discount assumption.</p><p class="small mb0"><strong>Loss:</strong> gross booked amounts less recoveries. Near misses contribute zero.</p></div>`)}</aside></div>`;}
function integrationsView(){return header('Integrations','Monitoring adapters and controlled verification fixtures.',btn(icon('refresh')+' Run fixture checks','run-fixtures','','primary'),'Data sources')+notice('<strong>Simulation only.</strong> These controls execute deterministic local fixtures. No credentials are requested, no external requests are made, and results never automatically approve requirements.','warning')+`<div class="grid3 mb16">${[['Identity fixture','Privileged accounts and MFA','Q05','99 of 100 privileged accounts protected'],['Cloud fixture','Encryption configuration','Q08','Connector unavailable → Unknown'],['Document freshness','Date-based policy checks','All evidence','Compare evidence expiry to demo snapshot']].map(([name,desc,q,out])=>`<div class="panel pad"><div class="tile-icon">${icon('link')}</div><h3 class="mt16">${name}</h3><p class="small">${desc}</p>${pill(q,'blue')}<hr class="divider"><p class="small mb0">${out}</p></div>`).join('')}</div>`+panel('Verification history','Source observations are recorded separately from requirement conclusions.',S.fixtureRuns.length?table(['Run','Adapter','Observation','Quality'],S.fixtureRuns.map(x=>({cells:[`<strong>${x.id}</strong><small>${e(recTimestamp(x.time))}</small>`,e(x.adapter),e(x.observation),pill(x.quality)]}))):empty('No fixture runs yet','Run a check to inspect observation quality and source availability.'))+notice('Production integration contract: tenant-scoped credentials, server-side scheduling, signed/provenanced observations, failure handling, retries and review-policy enforcement.','mini');}
function settingsView(){const tab=current.params.get('tab')||'demo';let body='';if(tab==='history')body=panel('Activity history','Append-only behavior is simulated locally; production requires a server-enforced audit trail.',S.activity.length?`<ul class="timeline">${S.activity.map(a=>`<li><strong>${e(a.text)}</strong><small>${e(a.actor)} · ${e(a.ref)} · ${e(recTimestamp(a.time))}</small></li>`).join('')}</ul>`:empty('No new activity','Complete a workflow to record its changes.'));else if(tab==='model')body=panel('Domain model','The demo data follows the requirement-centric architecture.',`<div class="pad"><div class="risk-chain">${[['Framework version','Canonical requirements + linked reusable question IDs + default quality policies'],['Program','Pinned framework ID + scope targets + requirement references + applicability and tailoring overrides'],['Assessment','One response set per program target; observations and evidence do not equal conclusions'],['Requirement evaluation','Target-specific reviewer conclusion, supporting evidence and source traceability'],['Vendor engagement','Supplier legal identity + service + owner + criticality; not the vendor name alone'],['RCSA','First-line proposal → independent challenge → approved residual rating'],['Loss event','Integer minor-unit gross + recovery ledger; net is derived']].map(([a,b])=>`<div class="chain-item"><small>${a}</small><strong>${b}</strong></div>`).join('')}</div></div>`);else body=`<div class="grid2">${panel('Demo controls','',`<div class="pad stack">${btn(icon('sun')+' Toggle theme','theme','','wide')}${btn(icon('download')+' Export workspace metadata','export-state','','wide')}${btn(icon('refresh')+' Reset demonstration data','reset','','wide danger')}<p class="small mb0">This workspace uses synthetic records stored in your browser. Reset removes this demo’s records and uploaded files, not other browser data. The JSON export contains metadata only; download file originals from Documents.</p></div>`)}${panel('Supporting workspaces','',`<div class="pad stack">${link(icon('link')+' Integrations & monitoring','integrations','wide')}${link(icon('shield')+' Controls & policies','controls','wide')}${link(icon('file')+' Documents','evidence','wide')}<p class="small mb0">No authentication, network API, notification delivery or production persistence is implemented. Do not load customer data into this prototype.</p></div>`)}</div>`;return header('Workspace settings','Demonstration state, architecture notes and local activity.',link('Integrations','integrations'),'Settings')+tabLinks([['Demo configuration','settings?tab=demo','demo'],['Architecture','settings?tab=model','model'],['Activity history','settings?tab=history','history']],tab)+body;}

/* Local interaction engine. All consequential demo actions validate again at commit. */
function openDialog(title,subtitle,body,saveLabel='',onSave=null,kind='modal'){
  const d=$('#dialog');if(d.open)d.close();lastFocus=document.activeElement;modalSave=onSave;
  d.className='dialog '+kind;d.setAttribute('aria-labelledby','dialog-title');
  d.innerHTML=`<form id="modal-form"><header class="dialog-head"><div><h2 id="dialog-title">${e(title)}</h2><small>${e(subtitle)}</small></div>${btn(icon('close'),'close-dialog','aria-label="Close dialog"','icon-only quiet')}</header><div class="dialog-body">${body}<div id="modal-error" role="alert" hidden></div></div><footer class="dialog-foot">${btn(saveLabel?'Cancel':'Close','close-dialog')}${saveLabel?`<button class="btn primary" type="submit">${e(saveLabel)}</button>`:''}</footer></form>`;
  d.showModal();d.scrollTop=0;
}
function closeDialog(){const d=$('#dialog');if(d.open)d.close();modalSave=null;if(lastFocus?.isConnected)lastFocus.focus();}
function fail(message){throw new Error(message);}
function requireValue(ok,message){if(!ok)fail(message);}
function values(form){return Object.fromEntries(new FormData(form));}
function checks(name,items,selected=[]){return `<div class="choice-list">${items.map(x=>{const [v,label]=Array.isArray(x)?x:[x,x];return `<label class="checkbox-row"><input type="checkbox" name="${e(name)}" value="${e(v)}" ${selected.includes(v)?'checked':''}><span>${e(label)}</span></label>`;}).join('')}</div>`;}
function validDate(v,label='Date',notFuture=true){requireValue(/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v+'T00:00:00Z')),label+' is invalid.');requireValue(new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v,label+' is invalid.');if(notFuture)requireValue(v<=S.asOf,label+' cannot be after the demonstration snapshot (13 November 2026).');return v;}
function bounded(v,min,max,label){const n=Number(v);requireValue(Number.isFinite(n)&&Number.isInteger(n)&&n>=min&&n<=max,`${label} must be an integer from ${min} to ${max}.`);return n;}
function minorUnits(v){const s=String(v).trim();requireValue(/^\d{1,12}(?:\.\d{1,2})?$/.test(s),'Enter a non-negative NGN amount with at most two decimal places, without separators.');const [a,b='']=s.split('.');const n=Number(a)*100+Number(b.padEnd(2,'0'));requireValue(Number.isSafeInteger(n),'Amount exceeds the supported precision.');return n;}
function filteredRows(){const rows=$$('[data-search]',$('#main-content'));let n=0;for(const row of rows){const match=(!filters.search||row.dataset.search.toLowerCase().includes(filters.search))&&(!filters.unit||row.dataset.unit===filters.unit)&&(!filters.matrix||row.dataset.matrix===filters.matrix);row.hidden=!match;if(match)n++;}if($('#filter-count'))$('#filter-count').textContent=rows.length?`${n} of ${rows.length} records`:'';if($('#no-match'))$('#no-match').hidden=!rows.length||n>0;}
function ensureAssessment(p,t){const key=assessmentKey(p,t);return S.assessments[key]||(S.assessments[key]={answers:{},evidence:{},status:'Draft',reviewedReqs:[]});}
function refreshProgress(p,t){const a=getAssessment(p,t),qs=uniqueQ(activeReqs(p)),n=qs.filter(q=>String(a.answers[q.id]??'').trim()).length;const x=$('.cycle-count',$('#main-content'));if(x)x.innerHTML=`${n}<span> / ${qs.length} answered</span>`;const bar=$('.progress i',$('#main-content'));if(bar)bar.style.width=`${n/qs.length*100}%`;}
function policy(p,q){return {...q,...p.rules?.[q.id]};}
function qualifiedEvidence(p,t,q,accepted=false){return S.evidence.filter(x=>x.program===p.id&&x.target===t&&x.question===q.id&&evQuality(x)==='Current'&&days(S.asOf,x.observed)<=policy(p,q).freshDays&&(!accepted||x.status==='Accepted'));}
function validateAnswers(p,t,qids,accepted=false){const a=getAssessment(p,t);for(const id of qids){const q=findQ(id),v=String(a.answers[id]??'').trim();requireValue(v,`${id}: answer “${q.title}”.`);if(q.type==='date'){validDate(v,id+' observation date');requireValue(days(S.asOf,v)<=policy(p,q).freshDays,`${id}: the observation is older than its ${policy(p,q).freshDays}-day policy. Refresh it before submission.`);}if(q.type==='number')bounded(v,0,1e9,id+' value');if(q.type==='choice')requireValue(['Yes','Partially','No'].includes(v),id+': choose a valid answer.');if(policy(p,q).evidence)requireValue(qualifiedEvidence(p,t,q,accepted).length,`${id}: ${accepted?'current, accepted':'current'} scoped evidence is required. ${accepted?'Review the evidence first.':'Link document for this program and target.'}`);}}
function startAdoption(id,target){const start=()=>{S.draft=null;selectedFramework=id;const d=draft();if(target){d.scopeType='vendor';d.targets=[target];d.respondents=['Vendor Management','Information Security'];}wizardStep=1;save();closeDialog();go('adopt');};if(S.draft){openDialog('Replace saved adoption draft?','Your published programs will not be changed.',`<p>A draft named <strong>${e(S.draft.name)}</strong> already exists. Replacing it discards that draft’s unsent configuration.</p>`,'Replace draft',start,'');}else start();}
function tailorRequirement(id){const d=draft(),r=findR(id);openDialog(r.code+' · '+r.title,'Tailoring is stored on this program, never on the source requirement.',`<div class="source-block"><span class="eyebrow">Canonical requirement · v${r.version}</span><p class="mb0">${e(r.source)}</p></div><div class="stack mt16">${select('applicable','Applicability',[['yes','Applicable'],['no','Not applicable']],d.excluded[id]?'no':'yes')}${area('override','Program-specific wording (optional)',d.overrides[id]||'','maxlength="2500"')}${area('reason','Not-applicable rationale',d.excluded[id]||'','maxlength="1500"')}<p class="field-help">Exclusion needs a rationale. The source requirement remains visible and traceable.</p><h3>Linked questions</h3>${r.questions.map(q=>`<div class="source-block small"><strong>${q}</strong> ${e(findQ(q).title)}</div>`).join('')}</div>`,'Save tailoring',f=>{const x=values(f);if(x.applicable==='no'){requireValue(x.reason.trim().length>=10,'Explain why the requirement is not applicable (at least 10 characters).');d.excluded[id]=x.reason.trim();}else delete d.excluded[id];if(x.override.trim())d.overrides[id]=x.override.trim();else delete d.overrides[id];save();render();});}
function questionRule(id){const d=draft(),q=findQ(id),z=policy(d,q);openDialog(id+' · Data quality','Quality policies describe observations; they are not operational bank controls.',`<div class="source-block">${e(q.title)}</div><div class="stack mt16">${input('freshDays','Maximum observation age (days)',z.freshDays,'number','required min="1" max="3650" step="1"')}${select('evidence','Evidence required',[['yes','Required'],['no','Optional']],z.evidence?'yes':'no')}${select('connector','External verification adapter',[['','No external verification'],['Identity fixture','Identity fixture · simulated'],['Cloud fixture','Cloud fixture · simulated']],z.connector||'')}${select('frequency','Monitoring cadence',['Daily','Weekly','Monthly'],z.frequency||'Daily')}${notice('Fixture adapters are local simulations. A timeout or unavailable source produces Unknown, never a compliance pass.','warning')}</div>`,'Save policy',f=>{const x=values(f);d.rules[id]={freshDays:bounded(x.freshDays,1,3650,'Freshness'),evidence:x.evidence==='yes',connector:x.connector,frequency:x.frequency};delete d.fixtureResult;save();render();});}
function assignRequirement(id){const d=draft();openDialog('Respondents · '+findR(id).code,'Requirement-specific assignment overrides the program default.',`<p class="small">Program default: ${e(d.respondents.join(', '))}</p>${select('mode','Assignment',[['default','Inherit program respondents'],['override','Use selected units']],d.assignments[id]?'override':'default')}<h3 class="mt16">Respondent units</h3>${checks('units',CS_SEED.units,d.assignments[id]||d.respondents)}`,'Save assignment',f=>{const x=values(f);if(x.mode==='default')delete d.assignments[id];else{const u=new FormData(f).getAll('units');requireValue(u.length,'Choose at least one respondent unit.');d.assignments[id]=u;}save();render();});}
function publishReview(){const d=draft(),errs=draftErrors(d);if(errs.length){openDialog('Resolve adoption settings','The program has not been created.',errs.map(s=>notice(e(s),'warning')).join(''));return;}openDialog('Publish compliance program','Creates a pinned baseline and unassessed obligations in this local workspace.',`<h3>${e(d.name)}</h3><div class="stat-list mt16"><div><span>Framework</span><strong>${e(fw(d.frameworkId).name)} · v${fw(d.frameworkId).version}</strong></div><div><span>Targets</span><strong>${d.targets.map(t=>e(targetName(t))).join('<br>')}</strong></div><div><span>Applicable requirements</span><strong>${activeReqs(d).length} per target</strong></div><div><span>Unique questions</span><strong>${uniqueQ(activeReqs(d)).length} per target</strong></div><div><span>Owner / reviewer</span><strong>${e(d.owner)} / ${e(d.reviewer)}</strong></div><div><span>Respondents</span><strong>${e(d.respondents.join(', '))}</strong></div><div><span>First assessment due</span><strong>${date(d.due)}</strong></div></div>${notice('Publishing does not imply compliance. Every applicable requirement starts as Not assessed. Notifications and recurring jobs are configuration previews, not delivered services.','mini')}`,'Publish program',()=>{requireValue(S.draft===d,'This draft has already been published.');const errors=draftErrors(d);requireValue(!errors.length,errors.join(' '));const p={...clone(d),id:uid('PRG'),frameworkVersion:fw(d.frameworkId).version,created:S.asOf,orgScopeIds:d.scopeType==='vendor'?[...new Set(d.targets.flatMap(id=>recScope('engagement',recRead('engagement',id))))]:(selectedScope()?[selectedScope()]:ORG.filter(n=>n.kind==='branch').map(n=>n.id)),evaluations:Object.fromEntries(d.targets.map(t=>[t,{}])),activity:[]};delete p.fixtureResult;S.programs.unshift(p);S.draft=null;audit(`Published ${p.name}; ${activeReqs(p).length} applicable requirements × ${p.targets.length} targets`,p.id,p.owner);go('program?id='+p.id);toast('Program published. All scoped obligations start as Not assessed.');},'');}
function fixtureRun(adapter){const identity=adapter==='Identity fixture';const x={id:uid('CHK'),time:new Date().toISOString(),adapter,observation:identity?'99/100 privileged accounts protected; 1 exception':adapter==='Cloud fixture'?'Source unavailable; no observation returned':`${S.evidence.filter(x=>evQuality(x)==='Needs refresh').length} expired evidence records`,quality:identity?'Exception detected':adapter==='Cloud fixture'?'Unknown':'Current'};S.fixtureRuns.unshift(x);S.fixtureRuns=S.fixtureRuns.slice(0,100);save();return x;}
function programRequirement(id){const p=prog(),t=selectedTarget(p),r=findR(id),a=getAssessment(p,t),v=evaluation(p,t,id),canReview=!p.excluded[id]&&a.status==='Submitted'&&!a.reviewedReqs?.includes(id);const qlist=r.questions.map(q=>findQ(q));const body=`<div class="source-block"><span class="eyebrow">Canonical · ${e(r.code)} · v${r.version}</span><p class="mb0">${e(r.source)}</p></div>${p.overrides[id]?`<div class="notice mini"><div><strong>Program tailoring</strong><br>${e(p.overrides[id])}</div></div>`:''}<div class="row wrap mt16">${pill(v.status)}<span class="small muted">${e(targetName(t))}</span></div><h3 class="mt16">Assessment trace</h3>${qlist.map(q=>`<div class="source-block small"><strong>${q.id} · ${e(q.title)}</strong><p class="mb0">Response: ${e(a.answers[q.id]||'Not submitted')}</p>${S.evidence.filter(x=>x.program===p.id&&x.target===t&&x.question===q.id).map(x=>`<div class="row wrap mt16"><span class="grow">${e(x.name)}</span>${pill(evQuality(x))}${pill(x.status)}${btn('Review','evidence-detail',`data-id="${x.id}"`,'quiet small')}</div>`).join('')}</div>`).join('')}<p class="small">Mapped controls: ${e(S.controls.filter(c=>c.reqs.includes(id)).map(c=>c.id+' '+c.title).join('; ')||'None recorded')}</p>${canReview?`<hr class="divider"><div class="stack">${select('reviewer','Acting reviewer',CS_SEED.people,p.reviewer)}${select('decision','Requirement conclusion',['Satisfied','Partially satisfied','Not satisfied'],'Partially satisfied')}${area('note','Evaluation rationale','','required minlength="10" maxlength="2000"')}${notice('A current accepted evidence set is required. A “Yes” response or passing API check does not by itself establish satisfaction.','mini')}</div>`:notice(a.reviewedReqs?.includes(id)?'This requirement has been evaluated for the submitted run. The accepted conclusion and audit event are retained.':'Submit the scoped assessment before recording a new reviewer conclusion.','mini')}`;
openDialog(r.code+' · '+r.title,'Scoped requirement evaluation',body,canReview?'Record conclusion':'',canReview?f=>{const x=values(f);requireValue(x.reviewer!==a.submittedBy,'Independent review required: the respondent cannot approve their own submission.');requireValue(a.status==='Submitted'&&!a.reviewedReqs?.includes(id),'This requirement has already been evaluated.');validateAnswers(p,t,r.questions,true);requireValue(x.note.trim().length>=10,'Provide an evaluation rationale.');p.evaluations[t]??={};p.evaluations[t][id]={status:x.decision,date:S.asOf,reviewer:x.reviewer,note:x.note.trim(),assessmentKey:assessmentKey(p,t),evidence:r.questions.flatMap(q=>qualifiedEvidence(p,t,findQ(q),true).map(z=>z.id))};a.reviewedReqs??=[];a.reviewedReqs.push(id);audit(`${r.code}: ${x.decision} for ${targetName(t)}`,p.id,x.reviewer);render();toast('Requirement evaluation recorded; the scoped denominator is unchanged.');}:null);}
function submitAssessment(){const p=prog(),t=selectedTarget(p),a=ensureAssessment(p,t);try{requireValue(a.status!=='Submitted','This run is already submitted.');validateAnswers(p,t,uniqueQ(activeReqs(p)).map(q=>q.id));}catch(err){openDialog('Assessment is not ready','No requirement outcomes were changed.',notice(e(err.message),'warning'));return;}openDialog('Submit assessment for review','Response submission is not an approval or compliance conclusion.',`<p><strong>${e(p.name)}</strong><br>${e(targetName(t))}</p><p>${uniqueQ(activeReqs(p)).length} answered questions will become read-only in this demonstration run.</p>${select('respondent','Submitting respondent',CS_SEED.people,p.owner)}`,'Submit assessment',f=>{requireValue(a.status!=='Submitted','Already submitted.');validateAnswers(p,t,uniqueQ(activeReqs(p)).map(q=>q.id));a.status='Submitted';a.submittedBy=values(f).respondent;a.submitted=S.asOf;a.reviewedReqs=[];audit('Assessment submitted for '+targetName(t),p.id,a.submittedBy);render();toast('Submitted. The reviewer can now inspect evidence and evaluate requirements.');},'');}
function fillAssessment(){const p=prog(),t=selectedTarget(p),a=ensureAssessment(p,t);requireValue(a.status!=='Submitted','Submitted responses cannot be changed.');openDialog('Load synthetic example responses','Existing draft answers will be replaced; no evidence is accepted automatically.',notice('This demo helper creates clearly named synthetic responses and evidence metadata. It does not upload files, verify facts or record compliance decisions.','warning'),'Load example responses',()=>{for(const q of uniqueQ(activeReqs(p))){a.answers[q.id]=q.type==='choice'?(q.id==='Q05'?'Partially':'Yes'):q.type==='date'?'2026-11-10':q.type==='number'?'1':'Synthetic example · accountable owner';if(policy(p,q).evidence&&!qualifiedEvidence(p,t,q).length)S.evidence.push({id:uid('EV'),name:`SYNTHETIC ${q.id} evidence.txt`,target:t,program:p.id,question:q.id,observed:S.asOf,expires:addDays(S.asOf,policy(p,q).freshDays),status:'Submitted',owner:p.owner,size:0,metadataOnly:true});}audit('Loaded synthetic draft responses and evidence metadata',p.id,p.owner);render();},'');}
function addEvidence(qid=''){const p=['program','assessment'].includes(current.name)?prog():S.programs[0],t=['program','assessment'].includes(current.name)?selectedTarget(p):p.targets[0];const scopes=S.programs.flatMap(z=>z.targets.map(y=>[z.id+'::'+y,z.name+' / '+targetName(y)]));openDialog('Link a document','No file content is uploaded or retained in this demonstration.',`<div class="stack">${select('scope','Program & assessment target',scopes,p.id+'::'+t)}${select('question','Question mapping',Q.map(q=>[q.id,q.id+' · '+q.title]),qid||'Q01')}${input('name','Document / source name','','text','required maxlength="180" placeholder="Example: privileged-access-review.pdf"')}${input('observed','Observation date',S.asOf,'date',`required max="${S.asOf}"`)}${select('owner','Evidence contributor',CS_SEED.people,p.owner)}${notice('Expiry is derived from the chosen program’s question freshness policy. Evidence enters the review queue as Submitted.','mini')}</div>`,'Add metadata',f=>{const x=values(f),[pid,target]=x.scope.split('::'),pg=S.programs.find(z=>z.id===pid),q=findQ(x.question);requireValue(pg&&pg.targets.includes(target),'Invalid target scope.');requireValue(uniqueQ(activeReqs(pg)).some(z=>z.id===q.id),'That question is not in this program’s applicable requirements.');validDate(x.observed,'Observation date');S.evidence.unshift({id:uid('EV'),name:x.name.trim(),target,program:pid,question:q.id,observed:x.observed,expires:addDays(x.observed,policy(pg,q).freshDays),status:'Submitted',owner:x.owner,size:0,metadataOnly:true});audit('Added evidence metadata: '+x.name,pg.id,x.owner);render();toast('Evidence metadata added. Review and freshness remain separate.');});}
function evidenceDetail(id){const x=S.evidence.find(z=>z.id===id);requireValue(x,'Evidence record not found.');const can=x.status!=='Accepted';openDialog(x.name,'Metadata preview · document bytes are not available in this demo.',`<div class="stat-list"><div><span>Evidence ID</span><strong>${x.id}</strong></div><div><span>Target</span><strong>${e(targetName(x.target))}</strong></div><div><span>Program / question</span><strong>${e(x.program||'No program')} / ${e(x.question)}</strong></div><div><span>Contributor</span><strong>${e(x.owner)}</strong></div><div><span>Observed / expiry</span><strong>${date(x.observed)} / ${date(x.expires)}</strong></div><div><span>Freshness</span>${pill(evQuality(x))}</div><div><span>Acceptance</span>${pill(x.status)}</div></div>${evQuality(x)!=='Current'?notice('This evidence is stale. Historical acceptance is retained, but stale evidence cannot support a new current evaluation.','warning'):''}${can?`<hr class="divider"><div class="stack">${select('reviewer','Acting reviewer',CS_SEED.people,'Ifeoma Nwosu')}${select('decision','Review decision',['Accept','Request changes'],'Accept')}${area('note','Review rationale','','required minlength="10" maxlength="1500"')}</div>`:notice('Acceptance is a demonstration decision; this record contains metadata only. It is not proof of the document’s contents.','mini')}`,can?'Record document review':'',can?f=>{const v=values(f);requireValue(v.reviewer!==x.owner,'The contributor cannot accept their own evidence.');if(v.decision==='Accept')requireValue(evQuality(x)==='Current','Expired evidence cannot be accepted as current. Add a refreshed observation.');requireValue(v.note.trim().length>=10,'Provide a review rationale.');x.status=v.decision==='Accept'?'Accepted':'Changes requested';x.review={by:v.reviewer,date:S.asOf,note:v.note.trim()};audit(`Evidence ${x.id}: ${x.status}`,x.program||x.id,v.reviewer);render();toast('Evidence review recorded. Requirement conclusions were not changed.');}:null);}
function newVendor(){openDialog('Add service engagement','A supplier can have multiple independently assessed service relationships.',`<div class="stack">${select('supplier','Supplier',[['new','Create new supplier'],...S.vendors.map(v=>[v.id,v.name])],'new')}${input('supplierName','New supplier name (new suppliers only)','','text','maxlength="150"')}${input('contact','New supplier contact email','','email','maxlength="180" placeholder="assurance@supplier.example"')}${input('country','Country','Nigeria','text','maxlength="80"')}${input('service','Service / engagement name','','text','required maxlength="150"')}${select('unit','Accountable unit',CS_SEED.units,'Technology')}${select('owner','Relationship owner',CS_SEED.people,'Sarah Adams')}${select('criticality','Service criticality',['Critical','High','Medium','Low'],'High')}${input('data','Data and processing in scope','','text','required maxlength="200"')}${input('renewal','Contract review date','2027-03-31','date','required')}</div>`,'Create engagement',f=>{const x=values(f);validDate(x.renewal,'Contract review date',false);let v=S.vendors.find(z=>z.id===x.supplier);if(!v){requireValue(x.supplierName.trim().length>2,'Enter a new supplier name.');requireValue(x.contact.trim(),'Enter a supplier contact email.');requireValue(!S.vendors.some(z=>z.name.toLowerCase()===x.supplierName.trim().toLowerCase()),'This supplier already exists. Select its existing identity.');v={id:uid('VEN'),name:x.supplierName.trim(),country:x.country.trim(),contact:x.contact.trim()};S.vendors.push(v);}const t={id:uid('ENG'),vendorId:v.id,service:x.service.trim(),unit:x.unit,owner:x.owner,criticality:x.criticality,status:'Onboarding',data:x.data.trim(),renewal:x.renewal};S.engagements.unshift(t);audit('Created service engagement '+t.service,t.id,t.owner);go('vendor?id='+t.id);});}
function vendorPortal(id){const t=S.engagements.find(x=>x.id===id),p=S.programs.find(x=>x.scopeType==='vendor'&&x.targets.includes(id));openDialog('Vendor response portal','Restricted-view design preview · not a security boundary.',`<h3>${e(targetName(id))}</h3>${notice('This panel shows only this engagement’s requests. In production, a separately authenticated, server-authorized portal must enforce that scope.','warning')}${p?`<div class="stat-list"><div><span>Requested assessment</span><strong>${e(p.name)}</strong></div><div><span>Due</span><strong>${date(p.due)}</strong></div><div><span>Bank contact</span><strong>${e(t.owner)}</strong></div></div><hr class="divider">${uniqueQ(activeReqs(p)).map(q=>`<div class="source-block small">${q.id} · ${e(q.title)}</div>`).join('')}${link('Open response workflow (bank operator demo)',`assessment?id=${p.id}&target=${id}`,'wide primary')}`:empty('No assessment request','Create an assurance program for this engagement first.')}`);}
function activateEngagement(id){const t=S.engagements.find(x=>x.id===id),ps=S.programs.filter(p=>p.scopeType==='vendor'&&p.targets.includes(id));const clear=ps.length&&ps.every(p=>{const n=posture(p,id);return n.all>0&&n.pass===n.all;});openDialog('Review service activation','Illustrative onboarding policy, not a regulatory activation rule.',`<h3>${e(t.service)}</h3><p>${e(targetName(id))}</p>${clear?notice('All requirements in linked assurance programs have current satisfied evaluations.','success'):notice('Activation is blocked: all applicable requirements in a linked assurance program must have a current Satisfied evaluation. Complete the assessment and independent review first.','warning')}${clear?`<label class="checkbox-row"><input type="checkbox" name="approval" required><span>Record that contract and business approvals have been reviewed in this demo.</span></label>`:''}`,clear?'Activate engagement':'',clear?()=>{t.status='Active';audit('Activated service engagement after assurance review',id,t.owner);render();}:null);}
function newRisk(){openDialog('Record a risk','Record an initial baseline; future RCSA proposals need independent review.',`<div class="stack">${input('title','Risk title','','text','required maxlength="180"')}${select('unit','Accountable unit',CS_SEED.units,'Technology')}${select('owner','Risk owner',CS_SEED.people,'Chidi Okafor')}${select('category','Risk category',['Technology','Process','Fraud','Third-party','People','External'],'Technology')}${area('cause','Cause','','required maxlength="1000"')}${area('event','Risk event','','required maxlength="1000"')}${area('impactText','Business impact','','required maxlength="1000"')}<div class="field-grid">${select('il','Inherent likelihood',['1','2','3','4','5'],'4')}${select('ii','Inherent impact',['1','2','3','4','5'],'4')}${select('rl','Initial residual likelihood',['1','2','3','4','5'],'3')}${select('ri','Initial residual impact',['1','2','3','4','5'],'4')}</div>${input('appetite','Risk appetite limit',9,'number','required min="1" max="25" step="1"')}${select('control','Primary control',S.controls.map(c=>[c.id,c.title]),S.controls[0].id)}</div>`,'Record risk',f=>{const x=values(f),residual=[bounded(x.rl,1,5,'Likelihood'),bounded(x.ri,1,5,'Impact')],a=bounded(x.appetite,1,25,'Appetite');const r={id:uid('RSK'),title:x.title.trim(),unit:x.unit,owner:x.owner,category:x.category,cause:x.cause.trim(),event:x.event.trim(),impact:x.impactText.trim(),inherent:[bounded(x.il,1,5,'Likelihood'),bounded(x.ii,1,5,'Impact')],residual,appetite:a,control:x.control,status:score(residual)>a?'Treat':'Monitor'};S.risks.unshift(r);S.controls.find(c=>c.id===r.control).risks.push(r.id);audit('Recorded initial risk baseline '+r.title,r.id,r.owner);render();});}
function riskDetail(id){const r=S.risks.find(x=>x.id===id),c=S.controls.find(x=>x.id===r.control),loss=S.losses.filter(x=>x.risk===id),cycles=S.cycles.filter(x=>x.risks.includes(id));openDialog(r.title,r.id+' · '+r.unit,`<div class="row between"><span>Inherent ${scoreBadge(r.inherent)}</span><span>Residual ${scoreBadge(r.residual)}</span>${pill(r.status,'amber')}</div><div class="risk-chain mt16">${[['Cause',r.cause],['Event',r.event],['Impact',r.impact],['Accountable owner',r.owner]].map(([l,v])=>`<div class="chain-item"><small>${l}</small><strong>${e(v)}</strong></div>`).join('')}</div><h3 class="mt16">Control implementation</h3><div class="source-block"><strong>${e(c?.title||'No control')}</strong><p>${pill(c?.effectiveness||'Unknown')}</p>${c?btn('Inspect control','control-detail',`data-id="${c.id}"`,'small'):''}</div><h3 class="mt16">Independent assessments</h3>${cycles.map(z=>`<div class="list-row"><span class="grow small">${e(z.name)}</span>${link('Open RCSA',`rcsa-review?id=${z.id}&risk=${id}`,'small')}</div>`).join('')||'<p class="small">No RCSA cycle yet.</p>'}<h3 class="mt16">Linked loss events</h3>${loss.map(l=>`<div class="list-row"><span class="grow small">${e(l.title)}<br>${ngn(l.gross-recoveries(l))} net</span>${btn('Open','loss-detail',`data-id="${l.id}"`,'small')}</div>`).join('')||'<p class="small">No recorded losses.</p>'}<div class="row wrap mt16">${btn('Record linked loss','new-loss',`data-risk="${id}"`)}${link('Key indicators','indicators')}</div>`);}
function newCycle(){openDialog('Create RCSA cycle','The cycle covers the current risks in the selected unit.',`<div class="stack">${input('name','Cycle name','','text','required maxlength="150" placeholder="Technology · Q1 2027"')}${select('unit','Business unit',CS_SEED.units,'Technology')}${select('owner','First-line owner',CS_SEED.people,'Chidi Okafor')}${select('reviewer','Independent reviewer',CS_SEED.people,'Ifeoma Nwosu')}${input('due','Due date','2026-12-15','date',`required min="${S.asOf}"`)}</div>`,'Create cycle',f=>{const x=values(f),rs=scopeItems('risks').filter(r=>r.unit===x.unit).map(r=>r.id);requireValue(rs.length,'This unit has no risks. Record a risk before creating a cycle.');requireValue(x.owner!==x.reviewer,'Assign a different person as the independent reviewer.');validDate(x.due,'Due date',false);requireValue(x.due>=S.asOf,'The due date cannot be before the snapshot.');const c={id:uid('RCSA'),name:x.name.trim(),unit:x.unit,owner:x.owner,reviewer:x.reviewer,due:x.due,risks:rs,reviews:{}};S.cycles.unshift(c);audit('Created RCSA cycle '+c.name,c.id,c.owner);go('rcsa-review?id='+c.id);});}
function rcsaSubmit(form){const c=S.cycles.find(x=>x.id===form.dataset.cycle),r=S.risks.find(x=>x.id===form.dataset.risk),x=values(form),old=c.reviews[r.id];requireValue(!['Submitted','Approved'].includes(old?.status),'This assessment is locked for review.');const ev=S.evidence.find(z=>z.id===x.evidence);requireValue(ev&&riskEvidence(r).some(x=>x.id===ev.id),'Select current internal evidence mapped to this control’s assessment objectives.');requireValue(x.rationale.trim().length>=15,'Provide at least 15 characters of assessment rationale.');const v={status:'Submitted',effectiveness:x.effectiveness,likelihood:bounded(x.likelihood,1,5,'Likelihood'),impact:bounded(x.impact,1,5,'Impact'),rationale:x.rationale.trim(),evidence:ev.id,submittedBy:c.owner,submitted:S.asOf,history:old?[...(old.history||[]),clone({...old,history:undefined})]:[]};c.reviews[r.id]=v;audit(`Submitted ${r.id} RCSA proposal; effective rating unchanged`,c.id,c.owner);render();toast('Proposal submitted. The effective residual rating has not changed.');}
function rcsaDecision(form){const c=S.cycles.find(x=>x.id===form.dataset.cycle),r=S.risks.find(x=>x.id===form.dataset.risk),v=c.reviews[r.id],x=values(form);requireValue(v?.status==='Submitted','Only a submitted proposal can be reviewed.');requireValue(x.reviewer!==v.submittedBy,'Self-approval is blocked. Choose an independent reviewer.');requireValue(x.note.trim().length>=10,'Provide a decision rationale of at least 10 characters.');const before=r.residual.join(' × ');if(x.decision==='Approve'){const ev=S.evidence.find(z=>z.id===v.evidence);requireValue(ev&&riskEvidence(r).some(x=>x.id===ev.id)&&ev.status==='Accepted','Accept current evidence mapped to this control’s objectives before approving the rating.');r.residual=[v.likelihood,v.impact];r.status=score(r.residual)>r.appetite?'Treat':'Monitor';v.status='Approved';}else v.status='Challenge requested';v.reviewedBy=x.reviewer;v.reviewed=S.asOf;v.decisionNote=x.note.trim();if(v.status==='Challenge requested')v.challenge=x.note.trim();audit(`${r.id} RCSA ${v.status}: ${before}${v.status==='Approved'?' → '+r.residual.join(' × '):' remains effective'}. ${x.note.trim()}`,c.id,x.reviewer);render();toast(v.status==='Approved'?'Approved rating is now effective in the risk register.':'Challenge recorded. The first line can revise and resubmit.');}
function newIndicator(){const eligible=scopeItems('risks');requireValue(eligible.length,'No risks exist in this scope. Register a risk first, or change the scope.');openDialog('Add risk or control indicator','Threshold direction and observation quality are independent.',`<div class="stack">${input('title','Indicator title','','text','required maxlength="160"')}${select('risk','Linked risk',eligible.map(r=>[r.id,r.title]),eligible[0].id)}${select('type','Indicator type',['KRI','KCI'],'KRI')}${input('unit','Measurement unit','count','text','required maxlength="40"')}${select('direction','Breach direction',[['above','Above maximum'],['below','Below minimum']],'above')}<div class="field-grid">${input('threshold','Breach threshold',10,'number','required step="any"')}${input('warning','Warning threshold',8,'number','required step="any"')}</div>${input('freshDays','Observation validity (days)',30,'number','required min="1" max="3650" step="1"')}</div>`,'Create indicator',f=>{const x=values(f),threshold=Number(x.threshold),warning=Number(x.warning);requireValue(scopeItems('risks').some(r=>r.id===x.risk),'The selected risk is no longer available in this scope.');requireValue(Number.isFinite(threshold)&&Number.isFinite(warning),'Enter valid numeric thresholds.');requireValue(x.direction==='above'?warning<=threshold:warning>=threshold,'The warning threshold must be on the safe side of the breach threshold.');const z={id:uid(x.type),title:x.title.trim(),risk:x.risk,type:x.type,unit:x.unit.trim(),direction:x.direction,threshold,warning,freshDays:bounded(x.freshDays,1,3650,'Validity'),value:null,observed:null,history:[]};S.indicators.unshift(z);audit('Added indicator without an observation: '+z.title,z.id);render();});}
function observeIndicator(id){const z=S.indicators.find(x=>x.id===id);openDialog(z.title,'Recording an observation does not modify a requirement evaluation.',`<div class="stack">${input('value','Observed value ('+e(z.unit)+')',z.value??'','number','required step="any"')}${input('observed','Observation date',S.asOf,'date',`required max="${S.asOf}"`)}${area('note','Source / observation note','','required minlength="10" maxlength="1500"')}<label class="checkbox-row"><input type="checkbox" name="action" checked><span>Create an action if the current observation breaches the threshold.</span></label></div>`,'Record observation',f=>{const x=values(f),n=Number(x.value);requireValue(Number.isFinite(n),'Enter a finite numeric observation.');validDate(x.observed,'Observation date');requireValue(!z.observed||x.observed>=z.observed,'This date precedes the latest reading. Historical readings must not replace the current observation.');requireValue(x.note.trim().length>=10,'Describe the observation source in at least 10 characters.');z.value=n;z.observed=x.observed;z.note=x.note.trim();z.history.push(n);z.observations??=[];z.observations.push({id:uid('OBS'),value:n,date:x.observed,note:x.note.trim(),sourceRef:x.note.trim(),recordedBy:recActor().name,recordedAt:new Date().toISOString()});if(x.action&&indicatorState(z)==='Breached'&&!S.tasks.some(t=>t.ref===id&&t.status==='Open')){const r=S.risks.find(r=>r.id===z.risk);S.tasks.unshift({id:uid('ACT'),title:'Investigate indicator breach: '+z.title,kind:'Remediation',owner:r.owner,ownerId:recUserId(r.owner),orgScopeId:r.orgScopeId,due:addDays(S.asOf,7),status:'Open',route:'indicators',ref:id});}audit(`Observed ${z.title}: ${n} ${z.unit} · ${indicatorState(z)}`,id);render();});}
function newLoss(riskid){openDialog('Record loss or near miss','NGN amounts are stored as integer kobo; net loss is derived.',`<div class="stack">${input('title','Event title','','text','required maxlength="180"')}${select('risk','Linked risk',scopeItems('risks').map(r=>[r.id,r.title]),riskid||scopeItems('risks')[0]?.id)}${select('type','Event classification',['Actual loss','Near miss'],'Actual loss')}${input('date','Occurrence date',S.asOf,'date',`required max="${S.asOf}"`)}${input('gross','Gross booked loss (NGN)','0','text','required inputmode="decimal" placeholder="8500000.00"')}${area('note','Event description','','required minlength="10" maxlength="2000"')}${notice('Near misses must have zero booked loss. Recoveries are separate dated entries added after recording the event. The accountable unit is inherited from the linked risk.','mini')}</div>`,'Record event',f=>{const x=values(f),r=S.risks.find(z=>z.id===x.risk),gross=minorUnits(x.gross);validDate(x.date,'Occurrence date');requireValue(x.type==='Near miss'?gross===0:gross>0,x.type==='Near miss'?'A near miss must have zero booked loss.':'A loss event needs a positive booked amount.');const z={id:uid('LOS'),title:x.title.trim(),risk:r.id,unit:r.unit,orgScopeId:r.orgScopeId,date:x.date,type:x.type,gross,recoveries:[],owner:r.owner,status:'Open',note:x.note.trim()};S.losses.unshift(z);audit(`Recorded ${z.type.toLowerCase()} ${z.id}; gross ${ngn(gross)}`,z.id,r.owner);go('losses');toast('Event recorded. Net loss is calculated from its recovery ledger.');});}
function lossDetail(id){const l=S.losses.find(x=>x.id===id);openDialog(l.title,l.id+' · '+l.unit,`<div class="stat-list"><div><span>Occurred</span><strong>${date(l.date)}</strong></div><div><span>Classification</span>${pill(l.type,'blue')}</div><div><span>Gross loss</span><strong>${ngn(l.gross)}</strong></div><div><span>Recovered</span><strong>${ngn(recoveries(l))}</strong></div><div><span>Net loss</span><strong>${ngn(l.gross-recoveries(l))}</strong></div><div><span>Risk</span><strong>${e(l.risk)}</strong></div></div>${l.note?`<p>${e(l.note)}</p>`:''}<h3 class="mt16">Recovery ledger</h3>${l.recoveries.length?table(['Received','Amount','Reference'],l.recoveries.map(x=>({cells:[date(x.date),ngn(x.amount),e(x.note)]}))):'<p class="small">No recoveries received.</p>'}${l.gross>recoveries(l)?btn(icon('plus')+' Record recovery','add-recovery',`data-id="${id}"`,'primary wide mt16'):notice(l.type==='Near miss'?'Near misses do not have monetary recoveries.':'The gross amount has been fully recovered.','mini')}${notice('Received recoveries cannot exceed gross booked loss. This ledger does not mix open risk exposure with realized loss.','mini')}`);}
function addRecovery(id){const l=S.losses.find(x=>x.id===id),out=l.gross-recoveries(l);openDialog('Record recovery','Outstanding amount: '+ngn(out),`<div class="stack">${input('amount','Amount received (NGN)','','text','required inputmode="decimal"')}${input('date','Received date',S.asOf,'date',`required min="${l.date}" max="${S.asOf}"`)}${input('note','Recovery reference / source','','text','required minlength="5" maxlength="250"')}</div>`,'Add recovery',f=>{const x=values(f),amount=minorUnits(x.amount);requireValue(amount>0,'Recovery amount must be positive.');requireValue(amount<=l.gross-recoveries(l),'Recovery cannot exceed the current outstanding gross loss.');validDate(x.date,'Recovery date');requireValue(x.date>=l.date,'Recovery cannot precede the loss event.');l.recoveries.push({id:uid('REC'),amount,date:x.date,note:x.note.trim()});audit(`Recorded ${ngn(amount)} recovery; net ${ngn(l.gross-recoveries(l))}`,id,l.owner);render();toast('Recovery recorded and net loss recalculated.');});}
function controlDetail(id){const c=S.controls.find(x=>x.id===id);openDialog(c.title,c.id+' · '+c.unit,`<div class="row between">${pill(c.effectiveness)}<span class="small">Owner: ${e(c.owner)}</span></div><h3 class="mt16">Requirement mappings</h3>${c.reqs.map(id=>`<div class="source-block"><strong>${findR(id).code}</strong> ${e(findR(id).title)}</div>`).join('')}<h3 class="mt16">Risk links</h3>${c.risks.map(id=>`<div class="list-row"><span class="grow small">${e(S.risks.find(x=>x.id===id)?.title||id)}</span>${btn('Inspect','risk-detail',`data-id="${id}"`,'small')}</div>`).join('')}${notice('This is the bank’s implementation. Its effectiveness does not automatically establish compliance with every linked obligation.','mini')}`);}
function newControl(){openDialog('Add control implementation','One bank control may address several requirements.',`<div class="stack">${input('title','Control name','','text','required maxlength="160"')}${select('unit','Business unit',CS_SEED.units,'Technology')}${select('owner','Control owner',CS_SEED.people,'Chidi Okafor')}${select('effectiveness','Reported effectiveness',['Not assessed','Effective','Partially effective','Ineffective'],'Not assessed')}<h3>Requirement mappings</h3>${checks('reqs',R.map(r=>[r.id,r.code+' · '+r.title]),[])}</div>`,'Add control',f=>{const x=values(f),ids=new FormData(f).getAll('reqs');requireValue(ids.length,'Select at least one requirement mapping.');const c={id:uid('CTL'),title:x.title.trim(),unit:x.unit,owner:x.owner,effectiveness:x.effectiveness,reqs:ids,risks:[]};S.controls.unshift(c);audit('Added bank control '+c.title,c.id,c.owner);render();});}
function newProcessing(){openDialog('Add processing activity','Record internal policy decisions; these defaults are not legal advice.',`<div class="stack">${input('name','Activity name','','text','required maxlength="160"')}${input('purpose','Processing purpose','','text','required maxlength="250"')}${select('unit','Business unit',CS_SEED.units,'Retail Operations')}${select('owner','Accountable owner',CS_SEED.people,'Sarah Adams')}${input('data','Data categories','','text','required maxlength="200"')}${select('vendor','Processing supplier',['Internal',...S.vendors.map(x=>x.name)],'Internal')}${input('retention','Approved retention policy reference','','text','required maxlength="200" placeholder="Internal retention schedule / pending review"')}</div>`,'Record activity',f=>{const x=values(f),z={...x,id:uid('ROPA'),dpia:'Not started'};S.processing.unshift(z);audit('Created processing activity '+z.name,z.id,z.owner);render();});}
function processingDetail(id){const x=S.processing.find(z=>z.id===id);openDialog(x.name,id+' · processing activity',`<div class="stat-list">${[['Purpose',x.purpose],['Data',x.data],['Supplier',x.vendor],['Owner',x.owner],['Retention policy',x.retention]].map(([a,b])=>`<div><span>${a}</span><strong>${e(b)}</strong></div>`).join('')}</div><div class="stack mt16">${select('reviewer','Acting reviewer',CS_SEED.people,'Ifeoma Nwosu')}${select('status','DPIA lifecycle',['Not started','In review','Approved'],x.dpia)}${area('note','Decision basis','','required minlength="15" maxlength="1500"')}${notice('Workflow illustration only. A production DPIA needs its structured assessment and source evidence, not just this metadata decision.','warning')}</div>`,'Record demo decision',f=>{const v=values(f);requireValue(v.reviewer!==x.owner,'Assign an independent reviewer.');x.dpia=v.status;x.review={by:v.reviewer,note:v.note,date:S.asOf};audit(`Processing activity DPIA state: ${x.dpia}`,id,v.reviewer);render();});}
function newAction(){openDialog('Create remediation action','A task tracks work; completing it does not prove a requirement is satisfied.',`<div class="stack">${input('title','Action title','','text','required maxlength="200"')}${select('owner','Accountable owner',CS_SEED.people,'Chidi Okafor')}${input('due','Due date',addDays(S.asOf,7),'date',`required min="${S.asOf}"`)}${input('ref','Source record ID (optional)','','text','maxlength="100"')}</div>`,'Create action',f=>{const x=values(f);validDate(x.due,'Due date',false);requireValue(x.due>=S.asOf,'Due date cannot be before the snapshot.');const z={...x,id:uid('ACT'),kind:'Remediation',status:'Open',route:'work'};S.tasks.unshift(z);audit('Created action '+z.title,z.ref,z.owner);render();});}
function taskDetail(id){const item=workItems().find(x=>x.id===id);requireValue(item,'This work item is unavailable in the current scope.');if(item.source&&item.source!=='task'){go(item.route);return;}const t=S.tasks.find(x=>x.id===id);requireValue(t,'Work item not found.');const can=t.status!=='Completed'&&t.kind==='Remediation';openDialog(t.title,t.kind+' · '+id,`<div class="stat-list"><div><span>Owner</span><strong>${e(t.owner)}</strong></div><div><span>Due</span><strong>${date(t.due)}</strong></div><div><span>Status</span>${pill(t.status)}</div><div><span>Source</span><strong>${e(t.ref)}</strong></div></div><div class="mt16">${link('Open source workspace',t.route||'work','wide')}</div>${can?`<div class="stack mt16">${area('note','Completion evidence / outcome','','required minlength="15" maxlength="2000"')}${notice('This marks the action completed only. Requirement and risk decisions retain their separate reviewers.','mini')}</div>`:notice(t.status==='Completed'?e(t.note||'This action is complete.'):'Complete the governed review in its source workspace. A task cannot substitute for evidence or assessment approval.','mini')}`,can?'Mark action completed':'',can?f=>{t.status='Completed';t.note=values(f).note.trim();t.completed=S.asOf;audit('Completed action '+t.title,t.ref,t.owner);render();}:null);}
function download(name,data,mime='application/json'){const b=new Blob([data],{type:mime}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Export generated from this local workspace.');}
function csvCell(v){
  // Keep numeric negatives numeric. Neutralize only text cells that can be formulas.
  let s=String(v??'');
  if(typeof v!=='number'&&(/^[\s\uFEFF]*[=+\-@]/.test(s)||/^[\t\r\n]/.test(s)))s="'"+s;
  return '"'+s.replace(/"/g,'""')+'"';
}
function exportCSV(name,headers,rows){download(name,'\uFEFF'+[headers,...rows].map(x=>x.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function exportLosses(){const items=scopedLosses();exportCSV('clearsight-demo-losses.csv',['event_id','title','risk_id','unit','occurred','classification','currency','gross','recovered','net','basis'],items.map(l=>[l.id,l.title,l.risk,l.unit,l.date,l.type,'NGN',(l.gross/100).toFixed(2),(recoveries(l)/100).toFixed(2),((l.gross-recoveries(l))/100).toFixed(2),'Synthetic; received-to-date recoveries']));}
function exportPrograms(){exportCSV('clearsight-demo-programs.csv',['program_id','program','type','target_id','target','applicable','current_evaluations','satisfied','partial','failed','stale','not_assessed','as_of'],scopeItems('programs').flatMap(p=>p.targets.map(t=>{const z=posture(p,t);return[p.id,p.name,p.scopeType,t,targetName(t),z.all,z.reviewed,z.pass,z.partial,z.failed,z.stale,z.unassessed,S.asOf];})));}
function searchDialog(){openDialog('Find a workspace or record','Search only this demonstration workspace.',`<label class="search">${icon('search')}<input id="global-query" placeholder="Program, service, risk or workspace…" aria-label="Search demo workspace" autofocus></label><div id="global-results" class="mt16"></div>`,'',null,'');globalResults('');setTimeout(()=>$('#global-query')?.focus(),30);}
function globalResults(query){const records=[...Object.entries(titles).filter(([k])=>!['adopt','program','vendor','assessment','rcsa-review'].includes(k)).map(([k,v])=>({name:v,kind:'Workspace',route:k})),...S.programs.map(x=>({name:x.name,kind:'Program',route:'program?id='+x.id})),...S.engagements.map(x=>({name:targetName(x.id),kind:'Engagement',route:'vendor?id='+x.id})),...S.risks.map(x=>({name:x.title,kind:x.id,action:'risk-detail',id:x.id}))].filter(x=>(x.name+' '+x.kind).toLowerCase().includes(query.toLowerCase())).slice(0,12);$('#global-results').innerHTML=records.length?records.map(x=>`<div class="list-row"><div class="grow"><strong>${e(x.name)}</strong><small>${e(x.kind)}</small></div>${x.action?btn('Open',x.action,`data-id="${x.id}"`,'small'):link('Open',x.route,'small')}</div>`).join(''):empty('No results','Try a shorter search term.');}
function inspectQuestion(id){const q=findQ(id);openDialog(q.id+' · '+q.title,'Reusable source question · program policies may override these defaults.',`<div class="stat-list"><div><span>Response type</span><strong>${q.type}</strong></div><div><span>Default freshness</span><strong>${q.freshDays} days</strong></div><div><span>Default document requirement</span><strong>${q.evidence?'Required':'Optional'}</strong></div><div><span>Verification</span><strong>${e(q.connector||'Manual')}</strong></div></div><h3 class="mt16">Requirement mappings</h3>${R.filter(r=>r.questions.includes(id)).map(r=>`<div class="source-block">${r.code} · ${e(r.title)}</div>`).join('')}${notice('The same question ID is answered once per program target, even when mapped to multiple requirements.','mini')}`);}
const actions={
  'menu':()=>$('#app').classList.add('nav-open'), 'menu-close':()=>$('#app').classList.remove('nav-open'),
  'close-dialog':closeDialog,
  'theme':()=>{S.theme=S.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=S.theme;save();},
  'search':searchDialog,
  'select-framework':el=>{selectedFramework=el.dataset.id;render();},
  'start-adoption':el=>startAdoption(el.dataset.id||selectedFramework),
  'save-draft':()=>{draft();save();toast('Adoption draft saved in this browser.');},
  'scope-type':el=>{const d=draft();d.scopeType=el.dataset.id;d.targets=d.scopeType==='bank'?['Meridian Bank']:[];save();render();},
  'wizard-step':el=>{wizardStep=bounded(el.dataset.id,1,3,'Wizard step');draft();save();render();},
  'tailor':el=>tailorRequirement(el.dataset.id),
  'question-rule':el=>questionRule(el.dataset.id),
  'assign-requirement':el=>assignRequirement(el.dataset.id),
  'test-draft':()=>{const d=draft();d.fixtureResult='Identity fixture: one MFA exception detected. Cloud fixture: source unavailable → Unknown.';fixtureRun('Identity fixture');fixtureRun('Cloud fixture');save();render();toast('Local verification fixtures recorded. No compliance conclusions changed.');},
  'publish-review':publishReview,
  'program-requirement':el=>programRequirement(el.dataset.id),
  'assessment-save':()=>{const p=prog(),t=selectedTarget(p);ensureAssessment(p,t);save();toast('Draft responses saved locally.');},
  'assessment-submit':submitAssessment,
  'fill-assessment':fillAssessment,
  'question-fixture':el=>{const q=findQ(el.dataset.id),p=prog(),z=fixtureRun(policy(p,q).connector||'Identity fixture');openDialog('Verification result','Simulated observation, not a requirement conclusion.',`<p>${e(q.title)}</p>${pill(z.quality)}<div class="source-block mt16">${e(z.observation)}</div>${notice('No external API call was made. Reviewer conclusions have not changed.','mini')}`);},
  'add-evidence':el=>addEvidence(el.dataset.question), 'evidence-detail':el=>evidenceDetail(el.dataset.id),
  'inspect-question':el=>inspectQuestion(el.dataset.id),
  'new-vendor':newVendor, 'vendor-assess':el=>startAdoption('FW-VENDOR',el.dataset.id),
  'vendor-portal':el=>vendorPortal(el.dataset.id), 'activate-engagement':el=>activateEngagement(el.dataset.id),
  'new-risk':newRisk,'risk-detail':el=>riskDetail(el.dataset.id),
  'matrix-filter':el=>{filters.matrix=el.dataset.id;$$('.heat-cell').forEach(x=>{x.classList.toggle('selected',x===el);x.setAttribute('aria-pressed',String(x===el));});filteredRows();$('#filter-count')?.scrollIntoView({block:'nearest'});},
  'clear-matrix':()=>{filters.matrix='';$$('.heat-cell').forEach(x=>{x.classList.remove('selected');x.setAttribute('aria-pressed','false');});filteredRows();},
  'new-cycle':newCycle,
  'new-indicator':newIndicator,'observe-indicator':el=>observeIndicator(el.dataset.id),
  'new-loss':el=>newLoss(el.dataset.risk),'loss-detail':el=>lossDetail(el.dataset.id),'add-recovery':el=>addRecovery(el.dataset.id),
  'new-control':newControl,'control-detail':el=>controlDetail(el.dataset.id),
  'new-processing':newProcessing,'processing-detail':el=>processingDetail(el.dataset.id),
  'new-action':newAction,'task-detail':el=>taskDetail(el.dataset.id),
  'export-losses':exportLosses,'export-programs':exportPrograms,
  'report-export':()=>download('clearsight-demo-report.json',JSON.stringify(reportData(),null,2)),
  'export-state':()=>download('clearsight-demo-workspace.json',JSON.stringify({...S,demonstrationOnly:true,includesFileBytes:false},null,2)),
  'print':()=>window.print(),
  'run-fixtures':()=>{fixtureRun('Identity fixture');fixtureRun('Cloud fixture');fixtureRun('Document freshness');audit('Executed local verification fixtures; no external connections','Integrations');render();},
  'reset':()=>openDialog('Reset this demonstration?','Only this demo’s local storage key will be replaced.',`<p>Programs, answers and records you created here will be removed. The original synthetic examples will be restored.</p><p>Export the local workspace first to retain a record of your changes.</p>`,'Reset demo',()=>{S=clone(CS_SEED);wizardStep=1;selectedFramework='FW-BANK';save();go('home');toast('Original demonstration data restored.');},'')
};
document.addEventListener('click',ev=>{
  const anchor=ev.target.closest('a');if(anchor?.dataset.questionAnchor){ev.preventDefault();$('#q-'+anchor.dataset.questionAnchor)?.scrollIntoView({block:'start',behavior:'auto'});return;}
  if(anchor?.getAttribute('href')==='#main-content'){ev.preventDefault();$('#main-content')?.focus();return;}
  if(anchor?.getAttribute('href')?.startsWith('#/')){if($('#dialog').open)closeDialog();$('#app').classList.remove('nav-open');}
  const el=ev.target.closest('[data-action]');if(!el)return;ev.preventDefault();const fn=actions[el.dataset.action];if(!fn){toast('This action is not available in the local demo.');console.error('Missing demo action',el.dataset.action);return;}
  try{if(typeof ui211RunAction==='function'){ui211RunAction(fn,el);return;}fn(el);}catch(err){if($('#dialog').open){const box=$('#modal-error');if(box){box.hidden=false;box.className='error';box.textContent=err.message;}}else toast(err.message);}
});
document.addEventListener('input',ev=>{const el=ev.target;if(el.matches('[data-filter]')){filters.search=el.value.toLowerCase().trim();filteredRows();}if(el.id==='global-query')globalResults(el.value);if(el.matches('[data-draft]')){draft()[el.dataset.draft]=el.value;save();if(el.dataset.draft==='name'&&$('#draft-name-preview'))$('#draft-name-preview').textContent=el.value||'Untitled program';}if(el.matches('[data-answer]')){const p=prog(),t=selectedTarget(p),a=ensureAssessment(p,t);if(a.status==='Submitted')return;a.answers[el.dataset.answer]=el.value;a.observedByQuestion??={};a.observedByQuestion[el.dataset.answer]=S.asOf;save();refreshProgress(p,t);}});
document.addEventListener('change',ev=>{const el=ev.target;try{
  if(el.matches('[data-unit-filter]')){filters.unit=el.value;filteredRows();}
  if(el.matches('[data-loss-period]')){S.lossPeriod=Number(el.value);save();go('losses?period='+el.value);}
  if(el.matches('[data-program-target]'))go(`program?id=${prog().id}&target=${encodeURIComponent(el.value)}&tab=${current.params.get('tab')||'overview'}`);
  if(el.matches('[data-target]')){const d=draft();d.targets=el.checked?[...new Set([...d.targets,el.dataset.target])]:d.targets.filter(x=>x!==el.dataset.target);save();render();}
  if(el.matches('[data-respondent]')){const d=draft();d.respondents=el.checked?[...new Set([...d.respondents,el.dataset.respondent])]:d.respondents.filter(x=>x!==el.dataset.respondent);save();render();}
  if(el.matches('[data-requirement]')){const id=el.dataset.requirement,d=draft();if(el.checked){delete d.excluded[id];save();render();}else{el.checked=true;tailorRequirement(id);$('#modal-form [name="applicable"]').value='no';}}
}catch(err){toast(err.message);}});
document.addEventListener('submit',ev=>{const form=ev.target;if(form.id==='modal-form'){ev.preventDefault();if(typeof ui211SubmitModal==='function'){ui211SubmitModal(form);return;}if(!modalSave)return;const callback=modalSave;try{for(const input of $$('input[required],textarea[required]',form)){requireValue(input.value.trim().length>0,'Complete all required fields with a meaningful value.');}const result=callback(form);if(result!==false)closeDialog();}catch(err){const box=$('#modal-error');box.hidden=false;box.className='error';box.textContent=err.message;box.scrollIntoView({block:'nearest'});}return;}if(form.dataset.submit){ev.preventDefault();try{if(form.dataset.submit==='rcsa-submit')rcsaSubmit(form);else if(form.dataset.submit==='rcsa-decision')rcsaDecision(form);}catch(err){const box=$('.form-error',form);box.textContent=err.message;box.scrollIntoView({block:'nearest'});}}});
document.addEventListener('keydown',ev=>{if((ev.metaKey||ev.ctrlKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();searchDialog();}if(ev.key==='Escape')$('#app').classList.remove('nav-open');});
$('#dialog').addEventListener('cancel',()=>{modalSave=null;if(lastFocus?.isConnected)setTimeout(()=>lastFocus.focus(),0);});
window.addEventListener('hashchange',()=>{if($('#dialog').open)closeDialog();render();});
window.CLEAR_SIGHT_DEMO=Object.freeze({getState:()=>clone(S),getReport:()=>clone(reportData()),getCanonical:()=>clone({requirements:R,questions:Q}),version:'2.8-demo'});
// First render runs after the Forms studio extension loads.
